  function applyTheme(theme, save) {
    var isLight = theme === "light";
    document.documentElement.setAttribute("data-theme", isLight ? "light" : "dark");
    if (document.body) {
      document.body.setAttribute("data-theme", isLight ? "light" : "dark");
